  // ── dangerous.ts: the /sh guard's reasons and explanations ──
  danger_data_destruction: "deletes or destroys data beyond recovery",
  danger_boot_recovery: "touches boot, backups or system recovery",
  danger_machine_state: "shuts down, restarts or reconfigures the machine",
