  danger_defenses: "disables the system's defenses (antivirus, firewall, BitLocker)",
  danger_traces: "clears system traces or logs",
  danger_evasion: "is an evasion vector: indirect, hidden or other-interpreter execution",
  danger_service: "affects the OpenCode service (it can cut this bot and every active session)",
  danger_processes: "kills processes or services (it can cut the service and this bot)",
  danger_software: "installs or uninstalls software",
  danger_network_egress: "reaches the network or transfers data outwards",
  danger_remote_exec: "runs commands on another machine",
  danger_persistence: "creates tasks or persistence that survives a reboot",
  danger_name_resolution: "resolves command names at runtime",
  danger_secret_env_drive: "lists environment variables (keys and tokens included)",
  danger_secret_ssh_dir: "reads private SSH keys",
  danger_secret_ssh_key: "reads a private SSH key",
  danger_secret_env_file: "reads an environment file with keys",
  danger_secret_creds: "reads browser credentials or profiles",
