  danger_registry_path: "operates on the system registry",
  danger_net_users: "creates or destroys local users or groups",
  danger_net_share: "reaches the network or mounts shares",
  danger_rm_no_target: "deletes files without saying which",
  danger_rm_project: "deletes the project's whole folder (.git included)",
